'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function savedFolder(){try{return sessionStorage.getItem('jianshan-nas-folder')||'';}catch{return '';}}
const state={configured:false,tab:location.hash.slice(1)||'library',photos:[],page:1,albumPhotos:new Map(),albumIds:[],pickerPage:1,nasFolder:savedFolder(),scan:null};
const labels={draft:'草稿',published:'已发布',trash:'回收站',queued:'等待处理',processing:'处理中',ready:'处理完成',failed:'处理失败',duplicate:'重复文件'};
const titles={library:['作品库','YOUR PHOTOGRAPHIC ARCHIVE'],upload:['上传照片','NEW WORKS'],nas:['NAS 导入','FROM YOUR PHOTO LIBRARY'],collections:['主题合集','STORIES IN SEQUENCE'],jobs:['导入任务','IMPORT ACTIVITY'],home:['首页策展','CURATE YOUR FIRST IMPRESSION'],storage:['存储与备份','YOUR PHOTO LIBRARY']};
let poll=null,searchTimer,pickerTimer,photoRequest=0,pickerRequest=0,folderRequest=0,scanRequest=0,jobsRequest=0,uploading=false;
if(!titles[state.tab])state.tab='library';
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body&&!(options.body instanceof File)?{'Content-Type':'application/json'}:{}),...options.headers}});const data=await response.json();if(!response.ok){if(response.status===401&&state.tab&&!['/api/login','/api/setup'].includes(url))await showAuth();throw Object.assign(new Error(data.error||'请求失败'),{status:response.status});}return data;}
function notify(message,error=false){$('#notice').textContent=message;$('#notice').classList.toggle('error',error);$('#notice').hidden=false;}
function busy(button,value){button.disabled=value;}
function errorBox(message){return `<div class="empty"><h3>暂时无法读取</h3><p>${esc(message)}</p></div>`;}
async function showAuth(){clearTimeout(poll);$$('dialog[open]').forEach(d=>d.close());const session=await api('/api/session');state.configured=session.configured;if(!session.authenticated)nasReview.clear();$('#auth').hidden=session.authenticated;$('#workspace').hidden=!session.authenticated;$('#auth-title').textContent=session.configured?'进入作品管理':'设置你的管理员密码';$('#auth-description').textContent=session.configured?'整理照片，把值得记住的瞬间发布到作品集。':'首次使用，设置至少 12 位密码。之后用这个密码管理作品。';$('#auth-submit').textContent=session.configured?'登录':'创建管理员并进入';$('#password').autocomplete=session.configured?'current-password':'new-password';await window.LoginChallenge.configure(!session.authenticated&&session.configured?session.turnstile:{enabled:false});if(session.authenticated)await loadWorkspace();}
async function loadWorkspace(){state.info=await api('/api/admin/state');$('#stats').innerHTML=['published','draft','trash'].map(s=>`<div class="stat"><strong>${state.info.counts[s]||0}</strong><span>${labels[s]}</span></div>`).join('');await switchTab(state.tab);}
$('#auth-form').addEventListener('submit',async event=>{event.preventDefault();if($('#auth-submit').disabled)return;window.LoginChallenge.setSubmitting(true);$('#auth-error').textContent='';try{const turnstileToken=window.LoginChallenge.getToken();await api(state.configured?'/api/login':'/api/setup',{method:'POST',body:JSON.stringify({password:$('#password').value,turnstileToken})});$('#password').value='';await showAuth();}catch(error){$('#auth-error').textContent=error.message;window.LoginChallenge.reset();}finally{window.LoginChallenge.setSubmitting(false);}});
$('#logout').onclick=async()=>{const button=$('#logout');busy(button,true);try{await api('/api/logout',{method:'POST'});await showAuth();}catch(error){notify('退出未完成：'+error.message,true);}finally{busy(button,false);}};
async function switchTab(tab,{historyMode='push'}={}){
 if(!titles[tab])return;
 if(state.tab!==tab)$('#notice').hidden=true;
 state.tab=tab;clearTimeout(poll);jobsRequest++;
 if(location.hash!=='#'+tab&&historyMode!=='none')history[location.hash&&historyMode==='push'?'pushState':'replaceState'](null,'','#'+tab);
 $$('.panel').forEach(el=>el.hidden=el.id!==tab);$$('.sidebar [data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));
 $('#section-title').textContent=titles[tab][0];$('#section-en').textContent=titles[tab][1];
 try{if(tab==='library'){state.info=await api('/api/admin/state');$('#stats').innerHTML=['published','draft','trash'].map(s=>`<div class="stat"><strong>${state.info.counts[s]||0}</strong><span>${labels[s]}</span></div>`).join('');await loadPhotos();}if(tab==='collections')await loadCollections();if(tab==='nas')await loadFolders();if(tab==='jobs')await loadJobs();if(tab==='home')await window.Studio?.loadHome();if(tab==='storage')await window.Studio?.loadStorage();}catch(error){if(state.tab===tab)notify(error.message,true);}
}
window.addEventListener('popstate',()=>switchTab(titles[location.hash.slice(1)]?location.hash.slice(1):'library',{historyMode:'none'}));
document.addEventListener('click',event=>{const tab=event.target.closest('[data-tab]');if(tab)switchTab(tab.dataset.tab);const close=event.target.closest('[data-close]');if(close)requestEditorClose(close.dataset.close);});
function hasLibraryFilters(){return !!($('#search').value.trim()||$('#status-filter').value||$('#picked-filter').checked||Number($('#rating-filter').value));}
function resetLibraryFilters(){clearTimeout(searchTimer);$('#search').value='';$('#status-filter').value='';$('#picked-filter').checked=false;$('#rating-filter').value='0';loadPhotos();}
async function loadPhotos(more=false){
 clearTimeout(searchTimer);
 const request=++photoRequest,page=more?state.page+1:1,button=$('#load-photos'),grid=$('#photo-grid');
 button.disabled=true;grid.setAttribute('aria-busy','true');
 if(!more)grid.innerHTML='<div class="empty">正在读取作品…</div>';
 try{
  const data=await api('/api/admin/photos?'+new URLSearchParams({status:$('#status-filter').value,q:$('#search').value,minRating:$('#rating-filter').value,order:$('#library-order').value,picked:$('#picked-filter').checked?'true':'',page,limit:36}));
  if(request!==photoRequest)return;
  state.page=page;state.photos=more?[...state.photos,...data.photos]:data.photos;
  if(!state.photos.length)window.Studio?.renderLibrary([]);
  grid.innerHTML=state.photos.length?(window.Studio?Studio.renderLibrary(state.photos):state.photos.map(p=>`<button class="photo-tile" data-edit="${p.id}">${esc(p.title)}</button>`).join('')):`<div class="empty"><h2>${hasLibraryFilters()?'当前条件下没有作品。':'这里，等待你的作品。'}</h2><p>${hasLibraryFilters()?'试试其他星级、状态或关键词。':'可以从上传照片或 NAS 导入开始。'}</p>${hasLibraryFilters()?'<button data-reset-library>清除全部筛选</button>':''}</div>`;
  $('#photo-count').textContent=`已显示 ${state.photos.length} / ${data.total} 幅作品`;button.hidden=!data.hasMore;button.textContent='加载更多';
 }catch(error){if(request!==photoRequest)return;if(!more){state.photos=[];grid.innerHTML=errorBox(error.message)+'<button data-retry-photos>重新加载作品</button>';$('#photo-count').textContent='';button.hidden=true;}else{notify(error.message,true);button.textContent='重试加载';}}
 finally{if(request===photoRequest){button.disabled=false;grid.removeAttribute('aria-busy');}}
}
$('#rating-filter').onchange=()=>loadPhotos();$('#library-order').onchange=()=>loadPhotos();$('#picked-filter').onchange=()=>loadPhotos();$('#status-filter').onchange=()=>loadPhotos();$('#search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadPhotos(),250);};$('#load-photos').onclick=()=>loadPhotos(true);
$('#photo-grid').onclick=event=>{const card=event.target.closest('[data-edit]');if(card)editPhoto(Number(card.dataset.edit));if(event.target.closest('[data-retry-photos]'))loadPhotos();if(event.target.closest('[data-reset-library]'))resetLibraryFilters();};
async function editPhoto(id){try{const p=await api('/api/admin/photos/'+id);state.edit=p;const form=$('#photo-form');form.reset();form.querySelector('.form-error').textContent='';for(const name of ['title','description','rating','privateNote','date','author','category','status','position'])form.elements[name].value=p[name]??'';form.elements.featured.checked=p.featured;form.elements.featuredOrder.value=p.featuredOrder;form.elements.equipmentId.innerHTML=`<option value="">${p.metadataCamera?'元数据相机 · '+esc(p.metadataCamera):'未指定 / 元数据缺失'}</option>`+state.info.equipment.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('');if(p.equipmentId&&!state.info.equipment.some(g=>g.id===p.equipmentId))form.elements.equipmentId.insertAdjacentHTML('beforeend',`<option value="${esc(p.equipmentId)}">${esc(p.equipmentName||p.equipmentId)}（历史器材）</option>`);form.elements.equipmentId.value=p.equipmentId||'';$('#edit-preview').src='/'+(p.largeSrc||p.src);$('#edit-source').textContent=p.isDemo?'示意作品 · 保留原作者署名与示例日期':`导入于 ${new Date(p.createdAt).toLocaleDateString('zh-CN')} · 未填写的拍摄日期不会用导入时间替代`;window.renderExif($('#edit-exif'),p.exifInfo,{demo:p.isDemo});$('#edit-collections').innerHTML=state.info.collections.length?state.info.collections.map(a=>`<label class="check"><input type="checkbox" name="collection" value="${a.id}" ${p.collections.includes(a.id)?'checked':''}>${esc(a.title)}</label>`).join(''):'暂无合集，可先保存作品，再创建合集。';$('#download-master').hidden=p.isDemo;$('#download-master').href='/api/admin/masters/'+p.id;window.Studio?.photoOpened(p);rememberForm($('#photo-form'));$('#editor').showModal();}catch(e){notify(e.message,true);}}
$('#photo-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button.primary');if(form.dataset.saving)return;form.dataset.saving='true';const submitters=[...form.querySelectorAll('button[type=submit]')];submitters.forEach(b=>busy(b,true));busy(button,true);form.querySelector('.form-error').textContent='';const data=Object.fromEntries(new FormData(form));data.version=state.edit.version;data.rating=Number(data.rating);data.status=event.submitter?.value||data.status;data.featured=form.elements.featured.checked;data.featuredOrder=Number(data.featuredOrder);data.collections=[...form.querySelectorAll('[name=collection]:checked')].map(el=>Number(el.value));try{await api('/api/admin/photos/'+state.edit.id,{method:'PATCH',body:JSON.stringify(data)});$('#editor').close();notify(data.status==='published'?'作品已发布，可以在前台查看。':data.status==='trash'?'作品已移入回收站。':'草稿已保存，仅自己可见。');state.info=await api('/api/admin/state');await loadWorkspace();}catch(e){form.querySelector('.form-error').textContent=e.message;}finally{delete form.dataset.saving;submitters.forEach(b=>busy(b,false));busy(button,false);}};
async function upload(files){if(!files.length||uploading)return;uploading=true;$('#dropzone').setAttribute('aria-busy','true');$('#upload-progress').textContent='准备上传…';let success=0;const failures=[];$('#files').disabled=true;for(const [i,file]of [...files].entries()){if(!/\.(jpe?g|png|heic|heif)$/i.test(file.name)){failures.push(file.name+'：请选择 JPEG、PNG 或 HEIC');continue;}if(file.size>100*1024*1024){failures.push(file.name+'：超过 100 MB');continue;}$('#upload-progress').textContent=`正在上传 ${i+1} / ${files.length}：${file.name}`;try{await api('/api/admin/uploads?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':file.type||'application/octet-stream'}});success++;}catch(e){failures.push(file.name+'：'+e.message);}}uploading=false;$('#dropzone').removeAttribute('aria-busy');$('#files').disabled=false;$('#files').value='';$('#upload-progress').innerHTML=`<p>已提交 ${success} 张照片。<button data-tab="jobs">查看处理进度 →</button></p>${failures.map(e=>`<p class="error">${esc(e)}</p>`).join('')}`;}
$('#files').onchange=e=>upload(e.target.files);const drop=$('#dropzone');for(const type of ['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('dragover');});drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragover');upload(e.dataTransfer.files);});
function navigateFolder(folder){state.nasFolder=folder;state.scan=null;scanRequest++;nasReview.clear();try{sessionStorage.setItem('jianshan-nas-folder',folder);}catch{}loadFolders();}
async function loadFolders(){
 const request=++folderRequest,folder=state.nasFolder,box=$('#nas-folders');
 $('#nas-scan').disabled=true;$('#nas-up').disabled=!folder;box.innerHTML='<p class="muted">正在读取 NAS 文件夹…</p>';
 try{const data=await api('/api/admin/nas/folders?folder='+encodeURIComponent(folder));if(request!==folderRequest)return;
  $('#nas-breadcrumb').textContent='Photos'+(data.folder?' / '+data.folder:'');$('#nas-up').disabled=!data.folder;
  box.innerHTML=data.folders.length?data.folders.map(f=>`<button data-folder="${esc(f.folder)}">▱ &nbsp; ${esc(f.name)} <span aria-hidden="true">→</span></button>`).join(''):'<p class="muted">这里没有子文件夹，可扫描当前文件夹中的照片。</p>';$('#nas-scan').disabled=false;
 }catch(e){if(request===folderRequest)box.innerHTML=errorBox(e.message+'。可点击“刷新文件夹”重试。');}
}
$('#nas-folders').onclick=e=>{const b=e.target.closest('[data-folder]');if(b)navigateFolder(b.dataset.folder);};$('#nas-up').onclick=()=>navigateFolder(state.nasFolder.split('/').slice(0,-1).join('/'));$('#nas-refresh').onclick=loadFolders;
const nasReview=window.createNasReview({root:$('#nas-scan-result'),onImport:async keys=>{
 if(!keys.length||!state.scan)return;
 const scanId=state.scan.id;
 const result=await api('/api/admin/nas/import',{method:'POST',body:JSON.stringify({scanId,keys})});
 if(state.scan?.id===scanId){nasReview.clear();state.scan=null;}
 if(state.tab==='nas')await switchTab('jobs');
 notify(`${result.jobs.length} 张照片已加入导入任务，完成后会保存为草稿。`);
}});
$('#nas-scan').onclick=async()=>{
 const request=++scanRequest,folder=state.nasFolder,button=$('#nas-scan');busy(button,true);nasReview.clear();state.scan=null;
 $('#nas-scan-result').innerHTML='<div class="empty">正在扫描照片，请稍候…</div>';
 try{const data=await api('/api/admin/nas/scan',{method:'POST',body:JSON.stringify({folder})});if(request!==scanRequest)return;state.scan=data;nasReview.setScan(data);}
 catch(e){if(request===scanRequest)$('#nas-scan-result').innerHTML=errorBox(e.message);}
 finally{if(request===scanRequest)busy(button,false);}
};
async function loadJobs(){const request=++jobsRequest;clearTimeout(poll);const data=await api('/api/admin/jobs');if(request!==jobsRequest||state.tab!=='jobs')return;$('#job-list').innerHTML=data.jobs.length?data.jobs.map(j=>`<article class="job-row"><div><strong>${esc(j.filename)}</strong><p>${j.source_type==='nas'?'NAS 文件夹':'网页上传'} · ${esc(new Date(j.created_at).toLocaleString('zh-CN',{hour12:false}))}</p>${j.error?`<p class="error">${esc(j.error)}</p>`:''}</div><span class="badge">${j.status==='ready'?(j.photo_status==='published'?'已发布':j.photo_status==='trash'?'已移入回收站':'草稿 · 仅自己可见'):labels[j.status]||esc(j.status)}</span><div>${j.photo_status==='published'?`<a class="quiet" href="/works/${j.photo_id}/" target="_blank" rel="noopener">查看前台</a>`:''}${j.photo_id?`<button data-job-photo="${j.photo_id}">查看作品 →</button>`:j.status==='failed'?`<button data-retry="${j.id}">重试</button>`:''}</div></article>`).join(''):'<div class="empty"><h2>还没有导入任务。</h2><p>上传照片或从 NAS 选择文件夹开始。</p></div>';if(data.active&&state.tab==='jobs')poll=setTimeout(()=>loadJobs().catch(e=>notify(e.message,true)),2000);}
$('#refresh-jobs').onclick=()=>loadJobs().catch(e=>notify(e.message,true));$('#job-list').onclick=async e=>{const retry=e.target.closest('[data-retry]'),photo=e.target.closest('[data-job-photo]');if(photo)await editPhoto(Number(photo.dataset.jobPhoto));if(retry){busy(retry,true);try{await api('/api/admin/jobs/'+retry.dataset.retry+'/retry',{method:'POST'});await loadJobs();}catch(err){notify(err.message,true);busy(retry,false);}}};
async function loadCollections(){state.info.collections=(await api('/api/admin/collections')).collections;$('#collection-grid').innerHTML=state.info.collections.length?state.info.collections.map(a=>`<button class="collection-tile" data-album="${a.id}"><span class="badge ${a.status}">${labels[a.status]}</span><h2>${esc(a.title)}</h2><p>${a.photos.length} 幅作品 · /collections/${esc(a.slug)}/</p></button>`).join(''):'<div class="empty"><h2>新建第一本主题影集。</h2></div>';}
$('#new-collection').onclick=()=>editAlbum();$('#collection-grid').onclick=e=>{const b=e.target.closest('[data-album]');if(b)editAlbum(Number(b.dataset.album));};
async function editAlbum(id){try{const a=state.info.collections.find(a=>a.id===id);state.album=a;state.albumIds=a?[...a.photos]:[];state.albumPhotos=new Map();const form=$('#album-form');form.reset();form.querySelector('.form-error').textContent='';$('#album-heading').textContent=a?'编辑合集':'新建合集';for(const key of ['title','slug','label','english','quote','description','story','status'])form.elements[key].value=a?.[key]||(key==='status'?'draft':'');form.elements.sortOrder.value=a?.sort_order||0;$('#picker-search').value='';if(a){await Promise.all(a.photos.map(async id=>{const p=await api('/api/admin/photos/'+id);state.albumPhotos.set(id,p);}));}state.albumBlocks=a?.layout?structuredClone(a.layout):[];renderSelected(a?.cover);await loadPicker();rememberForm($('#album-form'));$('#album-editor').showModal();}catch(e){notify(e.message,true);}}
function renderSelected(cover=Number($('#album-cover').value)){if(window.Studio)return Studio.renderAlbum(cover);const ids=state.albumIds;$('#album-selected').innerHTML=ids.length?ids.map((id,i)=>`<div class="selected-row"><span>${i+1}. ${esc(state.albumPhotos.get(id)?.title||'作品 '+id)}</span><button type="button" data-move="${id}" data-direction="-1" ${i===0?'disabled':''} aria-label="上移 ${esc(state.albumPhotos.get(id)?.title||'作品')}">↑</button><button type="button" data-move="${id}" data-direction="1" ${i===ids.length-1?'disabled':''} aria-label="下移 ${esc(state.albumPhotos.get(id)?.title||'作品')}">↓</button><button type="button" data-remove="${id}" aria-label="移出合集：${esc(state.albumPhotos.get(id)?.title||'作品')}">×</button></div>`).join(''):'<p class="muted">从下面选取作品；上下移动可以调整阅读顺序。</p>';$('#album-cover').innerHTML=ids.map(id=>`<option value="${id}">${esc(state.albumPhotos.get(id)?.title||'作品 '+id)}</option>`).join('');if(ids.includes(cover))$('#album-cover').value=cover;$$('#album-picker input').forEach(el=>el.checked=ids.includes(Number(el.value)));}
async function loadPicker(more=false){
 const request=++pickerRequest,page=more?state.pickerPage+1:1,box=$('#album-picker'),button=$('#picker-more');button.disabled=true;
 if(!more)box.innerHTML='<p class="muted">正在读取作品…</p>';
 try{const data=await api('/api/admin/photos?'+new URLSearchParams({limit:60,page,q:$('#picker-search').value}));if(request!==pickerRequest)return;
  state.pickerPage=page;data.photos.forEach(p=>state.albumPhotos.set(p.id,p));if(!more)box.innerHTML='';
  box.insertAdjacentHTML('beforeend',data.photos.map(p=>`<label><input type="checkbox" value="${p.id}" ${state.albumIds.includes(p.id)?'checked':''}><img src="/${esc(p.thumbSrc||p.src)}" alt="" loading="lazy"><span>${esc(p.title)}<br>${labels[p.status]}</span></label>`).join(''));
  if(!data.total)box.innerHTML='<p class="muted">没有匹配作品，换个关键词试试。</p>';button.hidden=!data.hasMore;button.textContent='加载更多作品';
 }catch(error){if(request!==pickerRequest)return;if(more){button.hidden=false;button.textContent='重试加载更多';notify(error.message,true);return;}box.innerHTML=`<p class="error">${esc(error.message)}</p><button type="button" data-retry-picker>重新加载作品</button>`;button.hidden=true;}
 finally{if(request===pickerRequest)button.disabled=false;}
}
$('#album-picker').addEventListener('click',e=>{if(e.target.closest('[data-retry-picker]'))loadPicker();});
$('#picker-search').oninput=()=>{clearTimeout(pickerTimer);pickerTimer=setTimeout(()=>loadPicker().catch(e=>notify(e.message,true)),300);};$('#picker-more').onclick=()=>loadPicker(true);$('#album-picker').onchange=e=>{const id=Number(e.target.value);if(e.target.checked&&!state.albumIds.includes(id))state.albumIds.push(id);else if(!e.target.checked)state.albumIds=state.albumIds.filter(i=>i!==id);renderSelected();};$('#album-selected').onclick=e=>{if(window.Studio)return Studio.albumAction(e);const m=e.target.closest('[data-move]'),r=e.target.closest('[data-remove]');if(m){const i=state.albumIds.indexOf(Number(m.dataset.move)),j=i+Number(m.dataset.direction);if(j>=0&&j<state.albumIds.length)[state.albumIds[i],state.albumIds[j]]=[state.albumIds[j],state.albumIds[i]];}if(r)state.albumIds=state.albumIds.filter(id=>id!==Number(r.dataset.remove));renderSelected();};
$('#album-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button.primary');busy(button,true);const data=Object.fromEntries(new FormData(form));data.version=state.album?.version;data.photos=state.albumIds;data.layout=state.albumBlocks;data.cover=Number(data.cover)||null;data.sortOrder=Number(data.sortOrder);try{await api('/api/admin/collections'+(state.album?'/'+state.album.id:''),{method:state.album?'PATCH':'POST',body:JSON.stringify(data)});$('#album-editor').close();await loadCollections();notify('合集已保存。');}catch(e){form.querySelector('.form-error').textContent=e.message;}finally{busy(button,false);}};
const formBaselines=new WeakMap();let pendingClose=null,discardFocus=null;
function formState(form){return JSON.stringify({fields:[...new FormData(form)],photos:form.id==='album-form'?state.albumIds:[],layout:form.id==='album-form'?state.albumBlocks:[]});}
function rememberForm(form){formBaselines.set(form,formState(form));}
function requestEditorClose(id){
 const editor=document.getElementById(id),form=editor.querySelector('form');
 if(id==='restore-dialog'){editor.close();return;}
 if(form&&formBaselines.get(form)!==formState(form)){pendingClose=editor;discardFocus=document.activeElement;$('#discard-dialog').showModal();$('#keep-editing').focus();}
 else editor.close();
}
for(const id of ['editor','album-editor'])document.getElementById(id).addEventListener('cancel',event=>{event.preventDefault();requestEditorClose(id);});
$('#keep-editing').onclick=()=>$('#discard-dialog').close();
$('#discard-editing').onclick=()=>{pendingClose?.close();pendingClose=null;$('#discard-dialog').close();};
$('#discard-dialog').addEventListener('close',()=>{if(pendingClose?.open&&discardFocus?.isConnected)discardFocus.focus();pendingClose=null;});
window.addEventListener('beforeunload',event=>{if(uploading||['editor','album-editor'].some(id=>{const dialog=document.getElementById(id),form=dialog.querySelector('form');return dialog.open&&formBaselines.get(form)!==formState(form);})){event.preventDefault();event.returnValue='';}});
showAuth().catch(e=>{document.body.innerHTML=`<div class="empty"><h1>后台服务暂时不可用</h1><p>${esc(e.message)}</p><button id="reconnect-backend">重新连接</button><a href="/">返回作品集</a></div>`;$('#reconnect-backend').onclick=()=>location.reload();});
